package com.example.lab4.controller; import com.example.lab4.dto.*; import com.example.lab4.service.*; import org.springframework.web.bind.annotation.*; import java.util.UUID; @RestController @RequestMapping("/api/support-requests") public class SupportRequestController { private final SupportRequestService service; public SupportRequestController(SupportRequestService s){service=s;} @PostMapping("/{id}/close") public SupportRequestView close(@PathVariable UUID id){return service.close(id);} }
